namespace {
char* copy_result(const std::string& text){auto* r=static_cast<char*>(std::malloc(text.size()+1));if(!r)return nullptr;std::memcpy(r,text.c_str(),text.size()+1);return r;}
std::size_t count_subshapes(const TopoDS_Shape& shape,TopAbs_ShapeEnum type){std::size_t n=0;for(TopExp_Explorer it(shape,type);it.More();it.Next())++n;return n;}
void append_point(std::ostringstream& out,const gp_Pnt& p,bool& first){if(!first)out<<',';out<<std::setprecision(12)<<p.X()<<','<<p.Y()<<','<<p.Z();first=false;}
void append_vec3(std::ostringstream& out,double x,double y,double z){out<<'['<<std::setprecision(12)<<x<<','<<y<<','<<z<<']';}
void append_point3(std::ostringstream& out,const gp_Pnt& p){append_vec3(out,p.X(),p.Y(),p.Z());}
void append_dir3(std::ostringstream& out,const gp_Dir& d){append_vec3(out,d.X(),d.Y(),d.Z());}
void append_point3_precise(std::ostringstream& out,const gp_Pnt& p){out<<'['<<std::setprecision(17)<<p.X()<<','<<p.Y()<<','<<p.Z()<<']';}
void append_dir3_precise(std::ostringstream& out,const gp_Dir& d){out<<'['<<std::setprecision(17)<<d.X()<<','<<d.Y()<<','<<d.Z()<<']';}
void append_point2(std::ostringstream& out,const gp_Pnt2d& p){out<<'['<<std::setprecision(17)<<p.X()<<','<<p.Y()<<']';}
void append_transform(std::ostringstream& out,const gp_Trsf& tr){out<<'[';for(int row=1;row<=3;++row){if(row>1)out<<',';out<<'[';for(int column=1;column<=4;++column){if(column>1)out<<',';out<<std::setprecision(17)<<tr.Value(row,column);}out<<']';}out<<']';}
const char* orientation_name(TopAbs_Orientation o){switch(o){case TopAbs_FORWARD:return "forward";case TopAbs_REVERSED:return "reversed";case TopAbs_INTERNAL:return "internal";case TopAbs_EXTERNAL:return "external";default:return "unknown";}}
const char* surface_name(GeomAbs_SurfaceType t){switch(t){case GeomAbs_Plane:return "plane";case GeomAbs_Cylinder:return "cylinder";case GeomAbs_Cone:return "cone";case GeomAbs_Sphere:return "sphere";case GeomAbs_Torus:return "torus";default:return "other";}}
const char* curve_name(GeomAbs_CurveType t){switch(t){case GeomAbs_Line:return "line";case GeomAbs_Circle:return "circle";case GeomAbs_Ellipse:return "ellipse";case GeomAbs_Hyperbola:return "hyperbola";case GeomAbs_Parabola:return "parabola";case GeomAbs_BezierCurve:return "bezier";case GeomAbs_BSplineCurve:return "bspline";default:return "other";}}
void append_manufacturing_face(std::ostringstream& out,const TopoDS_Face& face,std::size_t id,bool& first){BRepAdaptor_Surface s(face,true);if(!first)out<<',';out<<"{\"faceId\":"<<id<<",\"kind\":\""<<surface_name(s.GetType())<<"\",\"orientation\":\""<<orientation_name(face.Orientation())<<"\"";if(s.GetType()==GeomAbs_Plane){auto p=s.Plane();out<<",\"origin\":";append_point3(out,p.Location());out<<",\"normal\":";append_dir3(out,p.Axis().Direction());}else if(s.GetType()==GeomAbs_Cylinder){auto c=s.Cylinder();out<<",\"axisOrigin\":";append_point3(out,c.Location());out<<",\"axisDirection\":";append_dir3(out,c.Axis().Direction());out<<",\"radiusMm\":"<<std::setprecision(12)<<c.Radius();}else if(s.GetType()==GeomAbs_Sphere){auto sphere=s.Sphere();out<<",\"center\":";append_point3(out,sphere.Location());out<<",\"axisDirection\":";append_dir3(out,sphere.Position().Direction());out<<",\"xDirection\":";append_dir3(out,sphere.XAxis().Direction());out<<",\"yDirection\":";append_dir3(out,sphere.YAxis().Direction());out<<",\"radiusMm\":"<<std::setprecision(12)<<sphere.Radius();}out<<'}';first=false;}
void append_manufacturing_edge(std::ostringstream& out,const TopoDS_Edge& edge,std::size_t id,bool& first){const bool degenerated=BRep_Tool::Degenerated(edge);if(!first)out<<',';out<<"{\"edgeId\":"<<id;if(degenerated){TopTools_IndexedMapOfShape vertex_map;TopExp::MapShapes(edge,TopAbs_VERTEX,vertex_map);if(vertex_map.Extent()!=1){out<<",\"kind\":\"other\",\"orientation\":\""<<orientation_name(edge.Orientation())<<"\",\"closed\":"<<(edge.Closed()?"true":"false")<<",\"degenerated\":true}";first=false;return;}const gp_Pnt p=BRep_Tool::Pnt(TopoDS::Vertex(vertex_map(1)));out<<",\"kind\":\"other\",\"orientation\":\""<<orientation_name(edge.Orientation())<<"\",\"start\":";append_point3(out,p);out<<",\"end\":";append_point3(out,p);out<<",\"closed\":"<<(edge.Closed()?"true":"false")<<",\"degenerated\":true,\"degeneratedPoint\":";append_point3(out,p);out<<'}';first=false;return;}BRepAdaptor_Curve c(edge);double a=c.FirstParameter(),b=c.LastParameter();out<<",\"kind\":\""<<curve_name(c.GetType())<<"\",\"orientation\":\""<<orientation_name(edge.Orientation())<<"\",\"start\":";append_point3(out,c.Value(a));out<<",\"end\":";append_point3(out,c.Value(b));if(c.GetType()==GeomAbs_Circle){auto circle=c.Circle();out<<",\"center\":";append_point3(out,circle.Location());out<<",\"axisDirection\":";append_dir3(out,circle.Axis().Direction());out<<",\"radiusMm\":"<<std::setprecision(12)<<circle.Radius();}out<<",\"closed\":"<<(edge.Closed()?"true":"false")<<",\"degenerated\":false}";first=false;}
void append_display_edge(std::ostringstream& out,const TopoDS_Edge& edge,bool& first_edge){if(BRep_Tool::Degenerated(edge))return;BRepAdaptor_Curve c(edge);double a=c.FirstParameter(),b=c.LastParameter();if(!std::isfinite(a)||!std::isfinite(b)||b<a)return;int samples=c.GetType()==GeomAbs_Line?2:33;if(!first_edge)out<<',';out<<'[';bool fp=true;for(int i=0;i<samples;++i){double t=a+(b-a)*static_cast<double>(i)/static_cast<double>(samples-1);append_point(out,c.Value(t),fp);}out<<']';first_edge=false;}
}

extern "C" char* beblog_occt_inspect_step(const char* path){try{
 if(!path||!*path)return copy_result("{\"error\":\"Leerer STEP-Pfad\"}");STEPControl_Reader reader;if(reader.ReadFile(path)!=IFSelect_RetDone)return copy_result("{\"error\":\"STEP-Datei konnte von OCCT nicht gelesen werden\"}");if(reader.TransferRoots()<=0)return copy_result("{\"error\":\"STEP-Datei enthält keine übertragbare BRep-Geometrie\"}");TopoDS_Shape shape=reader.OneShape();if(shape.IsNull())return copy_result("{\"error\":\"OCCT lieferte eine leere Shape\"}");
 const auto solids=count_subshapes(shape,TopAbs_SOLID),faces=count_subshapes(shape,TopAbs_FACE),vertices=count_subshapes(shape,TopAbs_VERTEX);
 TopTools_IndexedMapOfShape edge_map;TopExp::MapShapes(shape,TopAbs_EDGE,edge_map);const auto edges=static_cast<std::size_t>(edge_map.Extent());
 std::size_t planes=0,cylinders=0,cones=0,spheres=0,tori=0,other=0;std::ostringstream radii,mfaces,medges,mwires;bool fr=true,ff=true,fe=true,fw=true;std::size_t face_id=0,wire_id=0;
 for(TopExp_Explorer it(shape,TopAbs_FACE);it.More();it.Next(),++face_id){auto face=TopoDS::Face(it.Current());BRepAdaptor_Surface s(face,true);switch(s.GetType()){case GeomAbs_Plane:++planes;break;case GeomAbs_Cylinder:++cylinders;if(!fr)radii<<',';radii<<std::setprecision(12)<<s.Cylinder().Radius();fr=false;break;case GeomAbs_Cone:++cones;break;case GeomAbs_Sphere:++spheres;break;case GeomAbs_Torus:++tori;break;default:++other;break;}append_manufacturing_face(mfaces,face,face_id,ff);
   auto outer_wire=BRepTools::OuterWire(face);for(TopExp_Explorer wit(face,TopAbs_WIRE);wit.More();wit.Next(),++wire_id){auto wire=TopoDS::Wire(wit.Current());const bool is_outer=!outer_wire.IsNull()&&wire.IsSame(outer_wire);if(!fw)mwires<<',';mwires<<"{\"wireId\":"<<wire_id<<",\"faceId\":"<<face_id<<",\"orientation\":\""<<orientation_name(wire.Orientation())<<"\",\"closed\":"<<(wire.Closed()?"true":"false")<<",\"outer\":"<<(is_outer?"true":"false")<<",\"edgeIds\":[";bool first_id=true;for(TopExp_Explorer eit(wire,TopAbs_EDGE);eit.More();eit.Next()){int idx=edge_map.FindIndex(eit.Current());if(idx<=0)continue;if(!first_id)mwires<<',';mwires<<(idx-1);first_id=false;}mwires<<"]}";fw=false;}}
 for(int i=1;i<=edge_map.Extent();++i)append_manufacturing_edge(medges,TopoDS::Edge(edge_map(i)),static_cast<std::size_t>(i-1),fe);
 constexpr double mesh_linear_deflection_mm=0.1,mesh_angular_deflection_rad=0.5;constexpr bool mesh_is_relative=false,mesh_in_parallel=true;constexpr std::size_t diagnostic_display_triangle_index=321;
 BRepMesh_IncrementalMesh mesher(shape,mesh_linear_deflection_mm,mesh_is_relative,mesh_angular_deflection_rad,mesh_in_parallel);std::size_t triangles=0,display_triangle_index=0;std::ostringstream mesh_vertices,mesh_face_ids,diagnostic_triangle;bool fv=true,ffi=true,has_diagnostic_triangle=false;if(mesher.IsDone()){std::size_t fid=0;for(TopExp_Explorer it(shape,TopAbs_FACE);it.More();it.Next(),++fid){auto face=TopoDS::Face(it.Current());TopLoc_Location loc;auto tri=BRep_Tool::Triangulation(face,loc);if(tri.IsNull())continue;triangles+=tri->NbTriangles();auto tr=loc.Transformation();for(int i=1;i<=tri->NbTriangles();++i,++display_triangle_index){int n1=0,n2=0,n3=0;tri->Triangle(i).Get(n1,n2,n3);const gp_Pnt a=tri->Node(n1).Transformed(tr),b=tri->Node(n2).Transformed(tr),c=tri->Node(n3).Transformed(tr);append_point(mesh_vertices,a,fv);append_point(mesh_vertices,b,fv);append_point(mesh_vertices,c,fv);if(!ffi)mesh_face_ids<<',';mesh_face_ids<<fid;ffi=false;if(display_triangle_index==diagnostic_display_triangle_index){has_diagnostic_triangle=true;BRepAdaptor_Surface surface(face,true);double u_min=0,u_max=0,v_min=0,v_max=0;BRepTools::UVBounds(face,u_min,u_max,v_min,v_max);diagnostic_triangle<<"{\"displayTriangleIndex\":"<<display_triangle_index<<",\"faceId\":"<<fid<<",\"nativeFaceOrdinal\":"<<fid<<",\"nativeTriangleIndex\":"<<(i-1)<<",\"nativeTriangleIndex1Based\":"<<i<<",\"nativeNodeIndices\":["<<n1<<','<<n2<<','<<n3<<"],\"rawPointsAfterTopLoc\":";diagnostic_triangle<<'[';append_point3_precise(diagnostic_triangle,a);diagnostic_triangle<<',';append_point3_precise(diagnostic_triangle,b);diagnostic_triangle<<',';append_point3_precise(diagnostic_triangle,c);diagnostic_triangle<<"],\"hasUVNodes\":"<<(tri->HasUVNodes()?"true":"false")<<",\"uvNodes\":";if(tri->HasUVNodes()){diagnostic_triangle<<'[';append_point2(diagnostic_triangle,tri->UVNode(n1));diagnostic_triangle<<',';append_point2(diagnostic_triangle,tri->UVNode(n2));diagnostic_triangle<<',';append_point2(diagnostic_triangle,tri->UVNode(n3));diagnostic_triangle<<']';}else diagnostic_triangle<<"null";diagnostic_triangle<<",\"face\":{\"getType\":\""<<surface_name(surface.GetType())<<"\",\"orientation\":\""<<orientation_name(face.Orientation())<<"\",\"uvBounds\":["<<std::setprecision(17)<<u_min<<','<<u_max<<','<<v_min<<','<<v_max<<"],\"topLocTransform\":";append_transform(diagnostic_triangle,tr);if(surface.GetType()==GeomAbs_Sphere){auto sphere=surface.Sphere();diagnostic_triangle<<",\"sphere\":{\"center\":";append_point3_precise(diagnostic_triangle,sphere.Location());diagnostic_triangle<<",\"axis\":";append_dir3_precise(diagnostic_triangle,sphere.Position().Direction());diagnostic_triangle<<",\"xAxis\":";append_dir3_precise(diagnostic_triangle,sphere.XAxis().Direction());diagnostic_triangle<<",\"yAxis\":";append_dir3_precise(diagnostic_triangle,sphere.YAxis().Direction());diagnostic_triangle<<",\"radiusMm\":"<<std::setprecision(17)<<sphere.Radius()<<'}';}else diagnostic_triangle<<",\"sphere\":null";diagnostic_triangle<<"}}";}}}}
 std::ostringstream display_edges;bool fde=true;for(int i=1;i<=edge_map.Extent();++i)append_display_edge(display_edges,TopoDS::Edge(edge_map(i)),fde);
 std::ostringstream out;out<<"{\"backend\":\"OCCT 8 / native C++ bridge\",\"nativeBrep\":true,\"faces\":"<<faces<<",\"edges\":"<<edges<<",\"vertices\":"<<vertices<<",\"solids\":"<<solids<<",\"surfaceTypes\":[{\"kind\":\"plane\",\"count\":"<<planes<<"},{\"kind\":\"cylinder\",\"count\":"<<cylinders<<"},{\"kind\":\"cone\",\"count\":"<<cones<<"},{\"kind\":\"sphere\",\"count\":"<<spheres<<"},{\"kind\":\"torus\",\"count\":"<<tori<<"},{\"kind\":\"other\",\"count\":"<<other<<"}],\"cylinderRadiiMm\":["<<radii.str()<<"],\"manufacturingFaces\":["<<mfaces.str()<<"],\"manufacturingEdges\":["<<medges.str()<<"],\"manufacturingWires\":["<<mwires.str()<<"],\"displayTriangles\":"<<triangles<<",\"displayVertices\":["<<mesh_vertices.str()<<"],\"displayFaceIds\":["<<mesh_face_ids.str()<<"],\"displayEdges\":["<<display_edges.str()<<"],\"diagnostics\":{\"candidate321\":{\"occtVersion\":\""<<OCC_VERSION_STRING_EXT<<"\",\"meshingParameters\":{\"linearDeflectionMm\":"<<mesh_linear_deflection_mm<<",\"isRelative\":"<<(mesh_is_relative?"true":"false")<<",\"angularDeflectionRad\":"<<mesh_angular_deflection_rad<<",\"inParallel\":"<<(mesh_in_parallel?"true":"false")<<"},\"nativeTriangle\":"<<(has_diagnostic_triangle?diagnostic_triangle.str():"null")<<"}},\"note\":\"Exaktes BRep bleibt Source of Truth. Manufacturing Faces, Edges und Wires exportieren analytische CAM-Semantik; Display-Geometrie bleibt rein visuell.\"}";return copy_result(out.str());
 }catch(...){return copy_result("{\"error\":\"OCCT-Fehler beim STEP-Import\"}");}}
extern "C" void beblog_occt_free_string(char* value){std::free(value);}
